"""One-shot PR #700 repair preparation; never included in the candidate commit."""
from __future__ import annotations
import hashlib
import json
from pathlib import Path
import subprocess
import sys
import tempfile
from unittest.mock import patch

ROOT = Path(sys.argv[2]).resolve()
sys.path.insert(0, str(ROOT))


def command(*args, **kwargs):
    return subprocess.check_output(args, cwd=ROOT, **kwargs)


def replace(path, before, after):
    file = ROOT / path
    text = file.read_text()
    if before in text:
        file.write_text(text.replace(before, after))


def edit():
    # Restrict replacements to current executable sources and selected contracts.
    # Retained measurements, receipts, research and historical reports are not relabelled.
    paths = [ROOT / 'Cargo.toml', ROOT / 'tools/toolchain.toml']
    for directory in ('apps', 'crates', 'tools'):
        for suffix in ('*.rs', '*.py', '*.toml'):
            paths.extend((ROOT / directory).rglob(suffix))
    paths.extend((ROOT / '.github/workflows').glob('*.yml'))
    paths.extend(ROOT / p for p in (
        'schemas/node-config-check.schema.json', 'examples/renderer-profile/profile.json',
        'wit/host-abi-phase3-v2.json', 'wit/host-abi-phase3-v3.json', 'wit/host-abi-phase3-v4.json',
        'docs/development/toolchain.md', 'docs/development/build-foundation.md',
        'docs/component-development/guest-sdk.md', 'docs/development/workflow-action-pins.md'))
    for path in set(paths):
        relative = path.relative_to(ROOT)
        replace(relative, '47.0.4', '48.0.3')
        replace(relative, '1.94.1', '1.95.0')
        replace(relative, '9376cdc5a5e25b16da71af47712785cf06b0d6d4', '46817827a5bfabe028bf34e1cce71fd40e2ff697')
    report = ROOT / 'docs/development/wasmtime-security-update.md'
    historical = report.read_text()
    assert historical.startswith('# Wasmtime 47.0.4 security baseline')
    report.write_text('''# Wasmtime 48.0.3 security baseline

## September 29, 2026 update

PR #700's fresh RustSec scan rejected Wasmtime 47.0.4 for
[RUSTSEC-2026-0315](https://rustsec.org/advisories/RUSTSEC-2026-0315.html)
(fuel-accounting amplification through `call_ref` and exception catches) and
[RUSTSEC-2026-0316](https://rustsec.org/advisories/RUSTSEC-2026-0316.html)
(dynamic record lifting beyond the hostcall fuel limit).
The database revision was `f23b768236fe2880e4cfa167da662cad8ca79240`.
Neither advisory lists a patched 47.x release. The exact dependency advances to
[Wasmtime 48.0.3](https://github.com/bytecodealliance/wasmtime/releases/tag/v48.0.3),
the first patched release in the next major line. Its upstream minimum Rust
version is 1.95.0; the workspace, isolated fixture and required MSRV lane use that
minimum while ordinary CI remains on Rust 1.97.1.

The update preserves the explicit feature set, disabled default features,
disabled parallel compilation and the sole private authenticated copying loader.
The reviewed upstream `Component::deserialize` entry still calls
`Engine::load_code_bytes`; it does not select the raw or file-backed loader.
The unsafe allowance and private proof requirements remain unchanged.
Required qualification includes the full workspace check, strict Clippy,
minimum-Rust build, fresh RustSec scan and native-loader/runtime regressions.
Check the current PR run for execution results; the September 13 results below
are historical and do not qualify this upgrade.

Rebuild and deploy the runtime and `latent-aot-compiler` together. Update the
approved compiler executable digest from the new binary. The runtime version,
engine layout policy and Angular renderer compatibility fingerprint advance
with the engine. Old native images and renderer receipts must not be relabelled;
rebuild them through the ordinary authenticated preparation and package paths.
The host WIT source digests and installed capability surface do not change.
Both the workspace and standalone Rust-authoring locks are generated by Cargo.
No advisory exception, ignored finding or skipped security gate is introduced.

## Historical September 13 baseline

''' + historical.replace('# Wasmtime 47.0.4 security baseline', '### Wasmtime 47.0.4 security baseline', 1))
    tests = ROOT / 'tools/tests/test_native_loader_boundary.py'
    text = tests.read_text()
    needle = '\n\nif __name__ == "__main__":'
    assert needle in text
    added = '''
    def test_current_engine_minimum_rust_and_host_descriptors_are_aligned(self) -> None:
        import json
        root = Path(__file__).resolve().parents[2]
        workspace = boundary.tomllib.loads((root / "Cargo.toml").read_text())["workspace"]
        pins = boundary.tomllib.loads((root / "tools/toolchain.toml").read_text())
        self.assertEqual(workspace["dependencies"]["wasmtime"]["version"], "=48.0.3")
        self.assertEqual(workspace["package"]["rust-version"], "1.95.0")
        self.assertEqual(pins["rust"]["msrv"], "1.95.0")
        self.assertEqual(pins["rust"]["dependencies"]["wasmtime"], "48.0.3")
        for name in ("v2", "v3", "v4"):
            with self.subTest(descriptor=name):
                descriptor = json.loads((root / f"wit/host-abi-phase3-{name}.json").read_text())
                self.assertEqual(descriptor["wasmtimeVersion"], "48.0.3")
        self.assertEqual(boundary.validate(root), [])

    def test_resolved_runtime_and_authoring_locks_use_the_patched_engine_family(self) -> None:
        root = Path(__file__).resolve().parents[2]
        for name in ("Cargo.lock", "tools/rust_capsule.lock"):
            with self.subTest(lock=name):
                packages = boundary.tomllib.loads((root / name).read_text())["package"]
                family = [p for p in packages if p["name"].startswith(("wasmtime", "pulley-"))]
                self.assertTrue(any(p["name"] == "wasmtime" for p in family))
                self.assertTrue(all(p["version"] == "48.0.3" for p in family))

    def test_real_standalone_authoring_lock_remains_in_the_workspace_closure(self) -> None:
        from tools.rust_capsule_project import locked_dependencies
        raw = locked_dependencies("security-regression-template")
        packages = boundary.tomllib.loads(raw.decode())["package"]
        self.assertEqual([p["version"] for p in packages if p["name"] == "wasmtime"], ["48.0.3"])
'''
    tests.write_text(text.replace(needle, '\n' + added + needle))


def locks():
    command('cargo', 'update', '-p', 'wasmtime', '--precise', '48.0.3')
    # Use the generated authoritative lock as a seed. Cargo resolves/prunes the
    # actual standalone manifest, not a hand-written transitive package list.
    from tools import rust_capsule_project as project
    with tempfile.TemporaryDirectory(prefix='lsf-security-lock-') as temporary:
        destination = Path(temporary) / 'project'
        with patch.object(project, 'locked_dependencies', return_value=(ROOT / 'Cargo.lock').read_bytes()):
            project.create(destination, 'greeting', 'latent-capsule-template')
        command('cargo', 'metadata', '--format-version', '1', '--manifest-path', str(destination / 'Cargo.toml'))
        (ROOT / 'tools/rust_capsule.lock').write_bytes((destination / 'Cargo.lock').read_bytes())
    project.locked_dependencies('verified-security-template')
    command('cargo', 'metadata', '--locked', '--format-version', '1', '--manifest-path', 'tools/native-fixture/Cargo.toml')


def inventory():
    from tools import ci_coverage as coverage
    path = ROOT / 'tools/ci/commands.json'
    data = json.loads(path.read_text())
    changed = set(command('git', 'diff', '--name-only', text=True).splitlines())
    allowed_owners = changed | {'tools/build_s3_fixture.py'}
    owners = coverage.delegated_owners(ROOT, coverage.commands(ROOT))
    for name in set(owners) | set(data['delegatedOwners']):
        if owners.get(name) != data['delegatedOwners'].get(name):
            assert name in allowed_owners, ('unexpected owner drift', name)
    data['delegatedOwners'] = owners
    cases = coverage.python_cases(ROOT)
    for name in set(cases) | set(data['pythonCases']):
        if cases.get(name) != data['pythonCases'].get(name):
            assert name in changed | {'tools/tests/test_s3_fixture_builder.py'}, ('unexpected case drift', name)
    data['pythonCases'] = cases
    data['pythonTestModules'] = sorted(cases)
    actual = coverage.commands(ROOT)
    assert set(actual) == set(data['after']), 'the repair must not add or remove required commands'
    for key, record in data['coverage'].items():
        if data['after'][record['after']] != actual[record['after']]:
            record['disposition'] = 'extended'
            record['reason'] = 'Advance the required MSRV to the patched Wasmtime 48.0.3 minimum; preserve command scope and gates.'
    data['after'] = actual
    data['workflowIdentities'] = coverage.workflow_identities(ROOT)
    path.write_text(json.dumps(data, indent=2, sort_keys=True) + '\n')
    coverage.validate(ROOT, path)
    print('Reviewed coverage owners and all Python cases match the exact candidate.')


def export():
    destination = Path(sys.argv[3]).resolve()
    destination.mkdir(parents=True, exist_ok=True)
    patch_bytes = command('git', 'diff', '--binary')
    assert patch_bytes
    (destination / 'candidate.patch').write_bytes(patch_bytes)
    changed = command('git', 'diff', '--name-only', text=True).splitlines()
    assert all(not name.startswith('.github/security/') for name in changed)
    assert '.github/maintenance/pr700_repair.py' not in changed
    assert '.github/workflows/pr700-repair.yml' not in changed
    (destination / 'files.json').write_text(json.dumps({name: hashlib.sha256((ROOT / name).read_bytes()).hexdigest() for name in changed}, indent=2) + '\n')
    print(command('git', 'diff', '--stat', text=True))


{'edit': edit, 'locks': locks, 'inventory': inventory, 'export': export}[sys.argv[1]]()
